1	package com.example.starter.evidence;
2	
3	import com.example.starter.error.ApiException;
4	import com.example.starter.evidence.dto.CommandRequest;
5	import com.example.starter.evidence.dto.CustodyChainView;
6	import com.example.starter.evidence.dto.EvidenceView;
7	import com.example.starter.evidence.dto.InspectionView;
8	import com.example.starter.evidence.dto.IntakeRequest;
9	import com.example.starter.evidence.dto.LoanCreateRequest;
10	import com.example.starter.evidence.dto.LoanReturnRequest;
11	import com.example.starter.evidence.dto.LoanView;
12	import com.example.starter.evidence.dto.SealInspectionRequest;
13	import com.example.starter.evidence.dto.TransferInitiateRequest;
14	import com.example.starter.evidence.dto.TransferView;
15	import com.fasterxml.jackson.databind.ObjectMapper;
16	import org.springframework.stereotype.Service;
17	import org.springframework.transaction.annotation.Transactional;
18	
19	import java.time.LocalDateTime;
20	import java.util.List;
21	import java.util.Optional;
22	
23	/**
24	 * 证物封存交接核心服务。所有写操作在单事务内完成：
25	 * 先锁定证物行（SELECT ... FOR UPDATE），再校验状态机并落库，最后写入幂等日志。
26	 * 交接记录与核验记录只追加；证物业务字段入库后不可修改。
27	 */
28	@Service
29	public class EvidenceService {
30	
31	    static final String OP_INTAKE = "INTAKE";
32	    static final String OP_TRANSFER_INITIATE = "TRANSFER_INITIATE";
33	    static final String OP_TRANSFER_ACCEPT = "TRANSFER_ACCEPT";
34	    static final String OP_TRANSFER_CANCEL = "TRANSFER_CANCEL";
35	    static final String OP_SEAL_INSPECTION = "SEAL_INSPECTION";
36	    static final String OP_LOAN_BORROW = "LOAN_BORROW";
37	    static final String OP_LOAN_RETURN = "LOAN_RETURN";
38	
39	    /**
40	     * 借出最长期限：72 小时。
41	     */
42	    static final long MAX_LOAN_HOURS = 72;
43	
44	    private final EvidenceRepository evidenceRepository;
45	    private final TransferRecordRepository transferRepository;
46	    private final SealInspectionRepository inspectionRepository;
47	    private final LoanRecordRepository loanRepository;
48	    private final CommandLogRepository commandLogRepository;
49	    private final ObjectMapper objectMapper;
50	    private final EvidenceClock clock;
51	
52	    public EvidenceService(EvidenceRepository evidenceRepository,
53	                           TransferRecordRepository transferRepository,
54	                           SealInspectionRepository inspectionRepository,
55	                           LoanRecordRepository loanRepository,
56	                           CommandLogRepository commandLogRepository,
57	                           ObjectMapper objectMapper,
58	                           EvidenceClock clock) {
59	        this.evidenceRepository = evidenceRepository;
60	        this.transferRepository = transferRepository;
61	        this.inspectionRepository = inspectionRepository;
62	        this.loanRepository = loanRepository;
63	        this.commandLogRepository = commandLogRepository;
64	        this.objectMapper = objectMapper;
65	        this.clock = clock;
66	    }
67	
68	    /**
69	     * 证物入库：初始状态 SEALED，保管人为操作人。evidenceKey 全局唯一。
70	     */
71	    @Transactional
72	    public StoredResponse intake(String actorId, IntakeRequest request, String requestHash) {
73	        Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
74	        if (replay.isPresent()) {
75	            return replay.get();
76	        }
77	        if (evidenceRepository.findByKey(request.evidenceKey()).isPresent()) {
78	            throw ApiException.conflict("证物已存在: " + request.evidenceKey());
79	        }
80	        LocalDateTime now = LocalDateTime.now();
81	        evidenceRepository.insert(request.evidenceKey(), request.caseKey(), request.category(),
82	                request.sealNo(), actorId, now);
83	        Evidence evidence = evidenceRepository.findByKey(request.evidenceKey()).orElseThrow();
84	        return record(request.commandKey(), OP_INTAKE, actorId, requestHash, 201, toView(evidence));
85	    }
86	
87	    /**
88	     * 发起交接：仅当前保管人，证物须为 SEALED，接收人须与发起人不同；成功后进入 TRANSFER_PENDING。
89	     */
90	    @Transactional
91	    public StoredResponse initiateTransfer(String actorId, String evidenceKey,
92	                                           TransferInitiateRequest request, String requestHash) {
93	        Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
94	        if (replay.isPresent()) {
95	            return replay.get();
96	        }
97	        Evidence evidence = lockEvidence(evidenceKey);
98	        // 并发下本事务可能在证物行锁上等待；持锁后复查幂等日志，重放先提交事务的首次结果。
99	        replay = checkReplay(request.commandKey(), requestHash);
100	        if (replay.isPresent()) {
101	            return replay.get();
102	        }
103	        if (request.toCustodian().equals(actorId)) {
104	            throw ApiException.badRequest("接收人不能与发起保管人相同");
105	        }
106	        requireSealIntact(evidence);
107	        requireCustodian(evidence, actorId);
108	        if (evidence.status() == EvidenceStatus.TRANSFER_PENDING) {
109	            throw ApiException.conflict("证物已存在待接收交接: " + evidenceKey);
110	        }
111	        if (evidence.status() == EvidenceStatus.BORROWED) {
112	            throw ApiException.conflict("借出期间禁止发起交接: " + evidenceKey);
113	        }
114	        LocalDateTime now = LocalDateTime.now();
115	        transferRepository.insert(evidenceKey, actorId, request.toCustodian(), now);
116	        evidenceRepository.updateStatus(evidenceKey, EvidenceStatus.TRANSFER_PENDING, now);
117	        TransferRecord pending = transferRepository.findPendingByEvidenceKey(evidenceKey).orElseThrow();
118	        return record(request.commandKey(), OP_TRANSFER_INITIATE, actorId, requestHash,
119	                200, toView(pending));
120	    }
121	
122	    /**
123	     * 接受交接：仅指定接收人；保管人原子切换为接收人并回到 SEALED。
124	     */
125	    @Transactional
126	    public StoredResponse acceptTransfer(String actorId, String evidenceKey,
127	                                         CommandRequest request, String requestHash) {
128	        Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
129	        if (replay.isPresent()) {
130	            return replay.get();
131	        }
132	        Evidence evidence = lockEvidence(evidenceKey);
133	        // 并发下本事务可能在证物行锁上等待；持锁后复查幂等日志，重放先提交事务的首次结果。
134	        replay = checkReplay(request.commandKey(), requestHash);
135	        if (replay.isPresent()) {
136	            return replay.get();
137	        }
138	        requireSealIntact(evidence);
139	        TransferRecord pending = requirePending(evidence, evidenceKey);
140	        if (!pending.toCustodian().equals(actorId)) {
141	            throw ApiException.conflict("操作人不是指定接收人: " + actorId);
142	        }
143	        LocalDateTime now = LocalDateTime.now();
144	        if (!transferRepository.decide(pending.id(), TransferStatus.ACCEPTED, now)) {
145	            throw ApiException.conflict("交接已被处理: " + evidenceKey);
146	        }
147	        evidenceRepository.updateCustody(evidenceKey, actorId, EvidenceStatus.SEALED, now);
148	        Evidence updated = evidenceRepository.findByKey(evidenceKey).orElseThrow();
149	        return record(request.commandKey(), OP_TRANSFER_ACCEPT, actorId, requestHash,
150	                200, toView(updated));
151	    }
152	
153	    /**
154	     * 取消交接：仅原保管人（发起人）可取消，接收人不能自行取消；证物回到 SEALED。
155	     */
156	    @Transactional
157	    public StoredResponse cancelTransfer(String actorId, String evidenceKey,
158	                                         CommandRequest request, String requestHash) {
159	        Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
160	        if (replay.isPresent()) {
161	            return replay.get();
162	        }
163	        Evidence evidence = lockEvidence(evidenceKey);
164	        // 并发下本事务可能在证物行锁上等待；持锁后复查幂等日志，重放先提交事务的首次结果。
165	        replay = checkReplay(request.commandKey(), requestHash);
166	        if (replay.isPresent()) {
167	            return replay.get();
168	        }
169	        requireSealIntact(evidence);
170	        TransferRecord pending = requirePending(evidence, evidenceKey);
171	        if (!pending.fromCustodian().equals(actorId)) {
172	            throw ApiException.conflict("仅原保管人可取消交接: " + actorId);
173	        }
174	        LocalDateTime now = LocalDateTime.now();
175	        if (!transferRepository.decide(pending.id(), TransferStatus.CANCELLED, now)) {
176	            throw ApiException.conflict("交接已被处理: " + evidenceKey);
177	        }
178	        evidenceRepository.updateStatus(evidenceKey, EvidenceStatus.SEALED, now);
179	        Evidence updated = evidenceRepository.findByKey(evidenceKey).orElseThrow();
180	        return record(request.commandKey(), OP_TRANSFER_CANCEL, actorId, requestHash,
181	                200, toView(updated));
182	    }
183	
184	    /**
185	     * 封条核验：仅当前保管人，待接收期间禁止核验。
186	     * 通过仅追加不可变记录；失败使证物进入 SEAL_BROKEN（终态）。
187	     */
188	    @Transactional
189	    public StoredResponse inspectSeal(String actorId, String evidenceKey,
190	                                      SealInspectionRequest request, String requestHash) {
191	        Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
192	        if (replay.isPresent()) {
193	            return replay.get();
194	        }
195	        Evidence evidence = lockEvidence(evidenceKey);
196	        // 并发下本事务可能在证物行锁上等待；持锁后复查幂等日志，重放先提交事务的首次结果。
197	        replay = checkReplay(request.commandKey(), requestHash);
198	        if (replay.isPresent()) {
199	            return replay.get();
200	        }
201	        requireCustodian(evidence, actorId);
202	        if (evidence.status() == EvidenceStatus.TRANSFER_PENDING) {
203	            throw ApiException.conflict("待接收期间禁止封条核验: " + evidenceKey);
204	        }
205	        if (evidence.status() == EvidenceStatus.BORROWED) {
206	            throw ApiException.conflict("借出期间禁止独立封条核验: " + evidenceKey);
207	        }
208	        LocalDateTime now = LocalDateTime.now();
209	        inspectionRepository.insert(evidenceKey, actorId, request.passed(), request.note(), now);
210	        if (!request.passed() && evidence.status() != EvidenceStatus.SEAL_BROKEN) {
211	            evidenceRepository.updateStatus(evidenceKey, EvidenceStatus.SEAL_BROKEN, now);
212	        }
213	        List<SealInspection> inspections = inspectionRepository.findByEvidenceKey(evidenceKey);
214	        SealInspection created = inspections.get(inspections.size() - 1);
215	        return record(request.commandKey(), OP_SEAL_INSPECTION, actorId, requestHash,
216	                200, toView(created));
217	    }
218	
219	    /**
220	     * 限时借出：仅当前保管人，证物须为 SEALED；进入 BORROWED，保管人不变。
221	     * 借用人与保管人不同；dueAt 为 UTC 时刻，须晚于当前且不超过 72 小时。
222	     * 待接收交接（TRANSFER_PENDING）或封条异常（SEAL_BROKEN）证物不能借出。
223	     */
224	    @Transactional
225	    public StoredResponse borrow(String actorId, String evidenceKey,
226	                                 LoanCreateRequest request, String requestHash) {
227	        Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
228	        if (replay.isPresent()) {
229	            return replay.get();
230	        }
231	        Evidence evidence = lockEvidence(evidenceKey);
232	        // 并发下本事务可能在证物行锁上等待；持锁后复查幂等日志，重放先提交事务的首次结果。
233	        replay = checkReplay(request.commandKey(), requestHash);
234	        if (replay.isPresent()) {
235	            return replay.get();
236	        }
237	        if (request.borrowerId().equals(actorId)) {
238	            throw ApiException.badRequest("借用人不能与当前保管人相同");
239	        }
240	        requireCustodian(evidence, actorId);
241	        if (evidence.status() == EvidenceStatus.SEAL_BROKEN) {
242	            throw ApiException.unprocessable("封条已异常，禁止借出: " + evidenceKey);
243	        }
244	        if (evidence.status() == EvidenceStatus.TRANSFER_PENDING) {
245	            throw ApiException.conflict("待接收交接期间禁止借出: " + evidenceKey);
246	        }
247	        if (evidence.status() == EvidenceStatus.BORROWED) {
248	            throw ApiException.conflict("证物已存在未归还借出: " + evidenceKey);
249	        }
250	        LocalDateTime nowUtc = clock.nowUtc();
251	        if (!request.dueAt().isAfter(nowUtc)) {
252	            throw ApiException.badRequest("应还时刻须晚于服务端当前时刻");
253	        }
254	        if (request.dueAt().isAfter(nowUtc.plusHours(MAX_LOAN_HOURS))) {
255	            throw ApiException.badRequest("借出期限不得超过 " + MAX_LOAN_HOURS + " 小时");
256	        }
257	        if (loanRepository.findByLoanKey(request.loanKey()).isPresent()) {
258	            throw ApiException.conflict("借出键已存在: " + request.loanKey());
259	        }
260	        loanRepository.insert(request.loanKey(), evidenceKey, actorId, request.borrowerId(),
261	                request.purpose(), nowUtc, request.dueAt(), LocalDateTime.now());
262	        evidenceRepository.updateStatus(evidenceKey, EvidenceStatus.BORROWED, LocalDateTime.now());
263	        LoanRecord loan = loanRepository.findByLoanKey(request.loanKey()).orElseThrow();
264	        return record(request.commandKey(), OP_LOAN_BORROW, actorId, requestHash,
265	                200, toView(loan));
266	    }
267	
268	    /**
269	     * 确认归还：仅借出时的保管人，必须指定本次 loanKey、封条是否完好及非空说明。
270	     * 借用人不能代为确认。完好回到 SEALED，异常进入 SEAL_BROKEN；
271	     * 借出归还结果、封条核验记录与证物状态在同一事务落库，历史不可覆盖。
272	     */
273	    @Transactional
274	    public StoredResponse returnLoan(String actorId, String evidenceKey,
275	                                     LoanReturnRequest request, String requestHash) {
276	        Optional<StoredResponse> replay = checkReplay(request.commandKey(), requestHash);
277	        if (replay.isPresent()) {
278	            return replay.get();
279	        }
280	        Evidence evidence = lockEvidence(evidenceKey);
281	        // 并发下本事务可能在证物行锁上等待；持锁后复查幂等日志，重放先提交事务的首次结果。
282	        replay = checkReplay(request.commandKey(), requestHash);
283	        if (replay.isPresent()) {
284	            return replay.get();
285	        }
286	        LoanRecord loan = loanRepository.findByLoanKey(request.loanKey())
287	                .orElseThrow(() -> ApiException.notFound("借出记录不存在: " + request.loanKey()));
288	        if (!loan.evidenceKey().equals(evidenceKey)) {
289	            throw ApiException.notFound("借出记录不属于该证物: " + request.loanKey());
290	        }
291	        if (loan.borrowerId().equals(actorId)) {
292	            throw ApiException.conflict("借用人不能代为确认归还: " + actorId);
293	        }
294	        if (!loan.custodianId().equals(actorId)) {
295	            throw ApiException.conflict("仅借出时的保管人可确认归还: " + actorId);
296	        }
297	        if (loan.status() != LoanStatus.ACTIVE || evidence.status() != EvidenceStatus.BORROWED) {
298	            throw ApiException.conflict("借出已归还，旧借出键不得再次结束借出: " + request.loanKey());
299	        }
300	        boolean sameActiveLoan = loanRepository.findActiveByEvidenceKey(evidenceKey)
301	                .map(active -> active.id().equals(loan.id())).orElse(false);
302	        if (!sameActiveLoan) {
303	            throw ApiException.conflict("借出记录与证物当前未归还借出不一致: " + request.loanKey());
304	        }
305	        LocalDateTime nowUtc = clock.nowUtc();
306	        if (!loanRepository.completeReturn(loan.id(), request.sealIntact(), request.note(), nowUtc)) {
307	            throw ApiException.conflict("借出已被并发归还: " + request.loanKey());
308	        }
309	        inspectionRepository.insert(evidenceKey, actorId, request.sealIntact(), request.note(),
310	                LocalDateTime.now());
311	        EvidenceStatus restored = request.sealIntact()
312	                ? EvidenceStatus.SEALED : EvidenceStatus.SEAL_BROKEN;
313	        evidenceRepository.updateStatus(evidenceKey, restored, LocalDateTime.now());
314	        LoanRecord returned = loanRepository.findByLoanKey(request.loanKey()).orElseThrow();
315	        return record(request.commandKey(), OP_LOAN_RETURN, actorId, requestHash,
316	                200, toView(returned));
317	    }
318	
319	    /**
320	     * 按借用人查询未归还借出及逾期记录（逾期仅为查询时刻标识，不改变任何状态）。
321	     */
322	    @Transactional(readOnly = true)
323	    public List<LoanView> listActiveLoansByBorrower(String borrowerId) {
324	        return loanRepository.findByBorrower(borrowerId).stream()
325	                .filter(loan -> loan.status() == LoanStatus.ACTIVE)
326	                .map(this::toView)
327	                .toList();
328	    }
329	
330	    /**
331	     * 查询当前操作人可交接的证物（本人保管且 SEALED）。
332	     */
333	    @Transactional(readOnly = true)
334	    public List<EvidenceView> listTransferable(String actorId) {
335	        return evidenceRepository.findTransferable(actorId).stream().map(this::toView).toList();
336	    }
337	
338	    /**
339	     * 查询完整保管链：证物当前状态 + 全部交接记录 + 全部借出记录 + 全部核验记录。
340	     */
341	    @Transactional(readOnly = true)
342	    public CustodyChainView custodyChain(String evidenceKey) {
343	        Evidence evidence = evidenceRepository.findByKey(evidenceKey)
344	                .orElseThrow(() -> ApiException.notFound("证物不存在: " + evidenceKey));
345	        List<TransferView> transfers = transferRepository.findByEvidenceKey(evidenceKey)
346	                .stream().map(this::toView).toList();
347	        List<LoanView> loans = loanRepository.findByEvidenceKey(evidenceKey)
348	                .stream().map(this::toView).toList();
349	        List<InspectionView> inspections = inspectionRepository.findByEvidenceKey(evidenceKey)
350	                .stream().map(this::toView).toList();
351	        return new CustodyChainView(toView(evidence), transfers, loans, inspections);
352	    }
353	
354	    private Evidence lockEvidence(String evidenceKey) {
355	        return evidenceRepository.findByKeyForUpdate(evidenceKey)
356	                .orElseThrow(() -> ApiException.notFound("证物不存在: " + evidenceKey));
357	    }
358	
359	    private void requireSealIntact(Evidence evidence) {
360	        if (evidence.status() == EvidenceStatus.SEAL_BROKEN) {
361	            throw ApiException.unprocessable("封条已异常，禁止交接相关操作: " + evidence.evidenceKey());
362	        }
363	    }
364	
365	    private void requireCustodian(Evidence evidence, String actorId) {
366	        if (!evidence.custodianId().equals(actorId)) {
367	            throw ApiException.conflict("操作人不是当前保管人: " + actorId);
368	        }
369	    }
370	
371	    private TransferRecord requirePending(Evidence evidence, String evidenceKey) {
372	        if (evidence.status() != EvidenceStatus.TRANSFER_PENDING) {
373	            throw ApiException.conflict("证物不存在待接收交接: " + evidenceKey);
374	        }
375	        return transferRepository.findPendingByEvidenceKey(evidenceKey)
376	                .orElseThrow(() -> ApiException.conflict("证物不存在待接收交接: " + evidenceKey));
377	    }
378	
379	    private Optional<StoredResponse> checkReplay(String commandKey, String requestHash) {
380	        return commandLogRepository.findByKey(commandKey).map(log -> {
381	            if (!log.requestHash().equals(requestHash)) {
382	                throw ApiException.conflict("幂等键已被不同参数使用: " + commandKey);
383	            }
384	            return new StoredResponse(log.responseStatus(), log.responseBody());
385	        });
386	    }
387	
388	    private StoredResponse record(String commandKey, String operation, String actorId,
389	                                  String requestHash, int status, Object body) {
390	        String json = toJson(body);
391	        commandLogRepository.insert(commandKey, actorId, operation, requestHash, status, json,
392	                LocalDateTime.now());
393	        return new StoredResponse(status, json);
394	    }
395	
396	    private String toJson(Object body) {
397	        try {
398	            return objectMapper.writeValueAsString(body);
399	        } catch (Exception e) {
400	            throw new IllegalStateException("响应序列化失败", e);
401	        }
402	    }
403	
404	    private EvidenceView toView(Evidence evidence) {
405	        return new EvidenceView(evidence.evidenceKey(), evidence.caseKey(), evidence.category(),
406	                evidence.sealNo(), evidence.custodianId(), evidence.status(),
407	                evidence.createdAt(), evidence.updatedAt());
408	    }
409	
410	    private TransferView toView(TransferRecord record) {
411	        return new TransferView(record.evidenceKey(), record.fromCustodian(), record.toCustodian(),
